// Pixel Dodger game
// Canvas element with id="game" is expected in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas element with id "game" not found');
    return;
  }
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Player settings
  const player = {
    w: 10,
    h: 10,
    x: width / 2 - 5,
    y: height - 15,
    speed: 4,
    color: '#00ff00',
  };

  // Block settings
  const blockSize = 10;
  const blocks = [];
  let blockSpawnInterval = 1500; // ms
  let lastSpawn = 0;
  let fallingSpeed = 2;

  let score = 0;
  let gameOver = false;

  // Input handling
  const keys = { left: false, right: false };
  document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = true;
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = true;
  });
  document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = false;
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = false;
  });

  function spawnBlock() {
    const x = Math.random() * (width - blockSize);
    blocks.push({ x, y: -blockSize, w: blockSize, h: blockSize, color: '#ff0000' });
  }

  function update(dt) {
    // Move player
    if (keys.left) player.x -= player.speed;
    if (keys.right) player.x += player.speed;
    // Keep within bounds
    if (player.x < 0) player.x = 0;
    if (player.x + player.w > width) player.x = width - player.w;

    // Spawn blocks based on interval
    if (performance.now() - lastSpawn > blockSpawnInterval) {
      spawnBlock();
      lastSpawn = performance.now();
    }

    // Update blocks
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += fallingSpeed;
      // Check collision with player
      if (
        b.x < player.x + player.w &&
        b.x + b.w > player.x &&
        b.y < player.y + player.h &&
        b.y + b.h > player.y
      ) {
        gameOver = true;
      }
      // Remove off-screen blocks and increment score
      if (b.y > height) {
        blocks.splice(i, 1);
        if (!gameOver) score++;
      }
    }

    // Gradually increase difficulty
    if (!gameOver && score % 10 === 0 && score !== 0) {
      fallingSpeed = Math.min(fallingSpeed + 0.2, 8);
      blockSpawnInterval = Math.max(blockSpawnInterval - 50, 400);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // Draw blocks
    blocks.forEach((b) => {
      ctx.fillStyle = b.color;
      ctx.fillRect(b.x, b.y, b.w, b.h);
    });
    // Draw score
    ctx.fillStyle = '#000000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#ffffff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Start loop
  requestAnimationFrame(loop);
})();
